1	package stowage
2	
3	import (
4		"sort"
5		"strconv"
6		"strings"
7	)
8	
9	// Adjust 提交一次调整，可同时包含多件货物的装载、卸下和移动。
10	//
11	// 调整编号遵循编号规则（去掉首尾空白后非空）。成功后以相同编号和
12	// 相同内容重复提交，返回首次成功的结果而不再改变配载，即使之后另有
13	// 调整也一样；同一编号用于不同内容被拒绝。失败的调整不占用编号，
14	// 可以修正后重试。内容比较按编号去空白后的原始字节进行：登记处能
15	// 区分的编号（包括含无效 UTF-8 字节的编号）在内容判断中同样区分。
16	// 卸下操作忽略目标值，其目标不参与内容比较；装载与移动的目标舱位
17	// 参与比较。
18	//
19	// 一次调整中的所有操作作为一个整体生效：任一操作不合法，整次调整
20	// 都不生效，货物归属与各舱位重量保持原样。合法性按全部操作完成后的
21	// 最终配载判断：舱位总重量不得超过承重；同一目的地的货物可以共舱，
22	// 不同目的地共舱时所有货物都必须允许混装。重量合计超过 int64 可表示
23	// 范围也会被拒绝。
24	func (r *Registry) Adjust(adjustmentID string, ops []Op) (*AdjustmentResult, error) {
25		r.mu.Lock()
26		defer r.mu.Unlock()
27	
28		aid := trimID(adjustmentID)
29		if aid == "" {
30			return nil, fail(ErrInvalidID, "", "调整编号为空")
31		}
32	
33		// f 构造带调整编号的错误。
34		f := func(kind ErrorKind, id string, format string, args ...any) *Error {
35			e := fail(kind, id, format, args...)
36			e.AdjustmentID = aid
37			return e
38		}
39	
40		// 幂等：编号已成功使用过。
41		if saved, ok := r.adjustments[aid]; ok {
42			if r.contents[aid] == canonicalKey(ops) {
43				return cloneResult(saved), nil
44			}
45			return nil, f(ErrAdjustmentIDConflict, aid, "调整编号 %s 已用于不同内容", aid)
46		}
47	
48		if len(ops) == 0 {
49			return nil, f(ErrEmptyAdjustment, aid, "调整 %s 不包含任何操作", aid)
50		}
51	
52		vops, final, affected, err := r.prepareOps(ops, f)
53		if err != nil {
54			return nil, err
55		}
56	
57		// 按最终配载校验承重与混装限制，返回第一个问题即拒绝整次调整；
58		// 拒绝原因到结构化错误的转换与 AmendCargo 共用。
59		if rej := r.firstRejection(final); rej != nil {
60			return nil, rejectionError(rej, f)
61		}
62	
63		// 全部合法，正式生效。先计算受影响舱位调整前后的重量；前后配载都
64		// 经过重量校验（原配载由历次成功操作累积而成，最终配载刚通过检查），
65		// 合计必然可以用 int64 表示。
66		cargoChanges := make([]CargoChange, 0, len(vops))
67		compChanges := make([]CompartmentChange, 0, len(affected))
68		for id := range affected {
69			before, _ := weightTotal(r.compartments[id].cargo)
70			after, _ := weightTotal(final[id])
71			compChanges = append(compChanges, CompartmentChange{
72				CompartmentID: id,
73				WeightBefore:  before,
74				WeightAfter:   after,
75			})
76		}
77		sort.Slice(compChanges, func(i, j int) bool {
78			return compChanges[i].CompartmentID < compChanges[j].CompartmentID
79		})
80	
81		for _, v := range vops {
82			c := v.cargo
83			// 正式生效的落点与预演模拟共用 relocate，去向沿用逐条校验时由
84			// routeFor 确定的同一份 from/to，因此生效结果与预览逐件对应。
85			relocate(c, v.rt, r.cargoSet(v.rt.from), r.cargoSet(v.rt.to))
86			c.compartmentID = v.rt.to
87			cargoChanges = append(cargoChanges, CargoChange{CargoID: c.id, From: v.rt.from, To: v.rt.to})
88		}
89		sort.Slice(cargoChanges, func(i, j int) bool {
90			return cargoChanges[i].CargoID < cargoChanges[j].CargoID
91		})
92	
93		result := &AdjustmentResult{
94			ID:                 aid,
95			CargoChanges:       cargoChanges,
96			CompartmentChanges: compChanges,
97		}
98		r.adjustments[aid] = result
99		r.contents[aid] = canonicalKey(ops)
100		return cloneResult(result), nil
101	}
102	
103	// validOp 是一条通过逐条校验的操作，附带其涉及的货物与由 routeFor
104	// 确定的去向。落点与变化记录只需货物和去向，原始操作与目标舱位在逐条
105	// 校验完成后不再需要。
106	type validOp struct {
107		cargo *cargo
108		rt    cargoRoute // 由 routeFor 确定的原舱位与最终舱位
109	}
110	
111	// prepareOps 逐条校验操作并在模拟配载上应用全部操作。
112	// 调用方必须持有 r.mu。任一操作不合法时返回该错误，最终配载与受影响
113	// 舱位集合只在全部操作合法时返回。受影响舱位包括各操作的原舱位与
114	// 目标舱位（交换中的两个舱位都会纳入）。
115	func (r *Registry) prepareOps(
116		ops []Op,
117		failf func(kind ErrorKind, id string, format string, args ...any) *Error,
118	) (vops []validOp, final map[string]map[string]*cargo, affected map[string]bool, err error) {
119		seen := make(map[string]bool)
120		vops = make([]validOp, 0, len(ops))
121		affected = make(map[string]bool)
122	
123		for _, op := range ops {
124			// 编号识别与内容比较共用 normalizeOp：货物编号与装载/移动目标
125			// 只去首尾空白，卸下目标视为空，字节级差异一律保留。
126			nop := normalizeOp(op)
127			cid := nop.CargoID
128			if cid == "" {
129				return nil, nil, nil, failf(ErrInvalidID, "", "货物编号为空")
130			}
131			c, ok := r.cargos[cid]
132			if !ok {
133				return nil, nil, nil, failf(ErrNotFound, cid, "货物 %s 不存在", cid)
134			}
135			if seen[cid] {
136				return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 在同一次调整中出现多次", cid)
137			}
138			seen[cid] = true
139	
140			// 逐条校验，确定操作种类与目标舱位；通过后由 routeFor 统一
141			// 固定去向，模拟落点、预览变化记录与正式生效共用这同一份去向。
142			// 先核对货物状态，再解析目标舱位：状态不符时即使目标空白或不
143			// 存在，也先报告状态问题。
144			var target *compartment
145			switch nop.Kind {
146			case OpLoad:
147				if c.compartmentID != "" {
148					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 已装载于舱位 %s，不能再次装载", cid, c.compartmentID)
149				}
150				t, err := r.targetCompartment(nop.Target, failf)
151				if err != nil {
152					return nil, nil, nil, err
153				}
154				target = t
155			case OpUnload:
156				if c.compartmentID == "" {
157					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能卸下", cid)
158				}
159				// 卸下忽略目标值，target 保持 nil。
160			case OpMove:
161				if c.compartmentID == "" {
162					return nil, nil, nil, failf(ErrStateMismatch, cid, "货物 %s 未装载，不能移动", cid)
163				}
164				t, err := r.targetCompartment(nop.Target, failf)
165				if err != nil {
166					return nil, nil, nil, err
167				}
168				if t.id == c.compartmentID {
169					return nil, nil, nil, failf(ErrDuplicateOp, cid, "货物 %s 已在舱位 %s，不能移动到原舱位", cid, t.id)
170				}
171				target = t
172			default:
173				return nil, nil, nil, failf(ErrInvalidOp, cid, "货物 %s 的操作种类 %d 无法识别", cid, int(nop.Kind))
174			}
175	
176			rt := routeFor(nop.Kind, c.compartmentID, target)
177			vops = append(vops, validOp{cargo: c, rt: rt})
178			touchedCompartments(affected, rt)
179		}
180	
181		// 在模拟配载上应用全部操作，落点与正式生效共用 relocate，判断以
182		// 完成后的最终状态为准。
183		final = make(map[string]map[string]*cargo, len(r.compartments))
184		for id, comp := range r.compartments {
185			set := make(map[string]*cargo, len(comp.cargo))
186			for cid, c := range comp.cargo {
187				set[cid] = c
188			}
189			final[id] = set
190		}
191		for _, v := range vops {
192			relocate(v.cargo, v.rt, final[v.rt.from], final[v.rt.to])
193		}
194		return vops, final, affected, nil
195	}
196	
197	// targetCompartment 查找装载或移动的目标舱位，是两种操作唯一的目标解析
198	// 入口。tid 必须已按编号识别规则去空白（见 normalizeOp）；空编号与未登记
199	// 编号分别按现有的结构化错误拒绝。调用方必须持有 r.mu。
200	func (r *Registry) targetCompartment(tid string, failf func(kind ErrorKind, id string, format string, args ...any) *Error) (*compartment, error) {
201		if tid == "" {
202			return nil, failf(ErrInvalidID, "", "目标舱位编号为空")
203		}
204		t, ok := r.compartments[tid]
205		if !ok {
206			return nil, failf(ErrNotFound, tid, "舱位 %s 不存在", tid)
207		}
208		return t, nil
209	}
210	
211	// evaluateFinal 按最终配载评估每个舱位的承重与混装限制，一个舱位可以
212	// 同时得到重量原因（超重或溢出）与混装原因。结果不保证顺序。
213	// 调用方必须持有 r.mu。
214	func (r *Registry) evaluateFinal(final map[string]map[string]*cargo) []*Rejection {
215		var rejs []*Rejection
216		for id, set := range final {
217			comp := r.compartments[id]
218	
219			// 重量原因：合计规则与快照共用同一入口；溢出优先，溢出时不提供
220			// 任何重量数值。
221			sum, ok := weightTotal(set)
222			var rej *Rejection
223			if !ok {
224				rej = &Rejection{
225					CompartmentID: id,
226					Kind:          ErrOverflow,
227					MaxWeight:     comp.maxWeight,
228				}
229			} else if sum > comp.maxWeight {
230				rej = &Rejection{
231					CompartmentID:   id,
232					Kind:            ErrOverweight,
233					MaxWeight:       comp.maxWeight,
234					UsedWeight:      sum,
235					RemainingWeight: comp.maxWeight - sum,
236					Overweight:      sum - comp.maxWeight,
237				}
238			}
239	
240			// 混装原因：不同目的地共舱时，列出全部不允许混装的货物。
241			destinations := make(map[string][]string)
242			destSet := make(map[string]bool)
243			var offenders []string
244			for _, c := range set {
245				destinations[c.destination] = append(destinations[c.destination], c.id)
246				destSet[c.destination] = true
247				if !c.allowMixed {
248					offenders = append(offenders, c.id)
249				}
250			}
251			if len(destSet) > 1 && len(offenders) > 0 {
252				dests := make([]MixedDestination, 0, len(destinations))
253				for dest, ids := range destinations {
254					sorted := append([]string(nil), ids...)
255					sort.Strings(sorted)
256					dests = append(dests, MixedDestination{Destination: dest, CargoIDs: sorted})
257				}
258				sort.Slice(dests, func(i, j int) bool {
259					return dests[i].Destination < dests[j].Destination
260				})
261				sort.Strings(offenders)
262				mr := &Rejection{
263					CompartmentID:  id,
264					Kind:           ErrMixedLoading,
265					MaxWeight:      comp.maxWeight,
266					Destinations:   dests,
267					OffendingCargo: offenders,
268				}
269				if rej != nil {
270					rejs = append(rejs, rej, mr)
271				} else {
272					rejs = append(rejs, mr)
273				}
274			} else if rej != nil {
275				rejs = append(rejs, rej)
276			}
277		}
278		return rejs
279	}
280	
281	// firstRejection 以与正式调整一致的顺序返回第一个拒绝原因；没有则 nil。
282	// 调用方必须持有 r.mu。
283	func (r *Registry) firstRejection(final map[string]map[string]*cargo) *Rejection {
284		rejs := r.evaluateFinal(final)
285		if len(rejs) == 0 {
286			return nil
287		}
288		sort.Slice(rejs, func(i, j int) bool {
289			if rejs[i].CompartmentID != rejs[j].CompartmentID {
290				return rejs[i].CompartmentID < rejs[j].CompartmentID
291			}
292			return rejKindOrder(rejs[i].Kind) < rejKindOrder(rejs[j].Kind)
293		})
294		return rejs[0]
295	}
296	
297	// rejKindOrder 规定同一舱位的拒绝原因次序：重量（超重/溢出）先于混装。
298	func rejKindOrder(k ErrorKind) int {
299		switch k {
300		case ErrOverflow, ErrOverweight:
301			return 0
302		default:
303			return 1
304		}
305	}
306	
307	// firstOffender 返回混装原因中编号最小的货物，用于错误说明。
308	func (x *Rejection) firstOffender() string {
309		if len(x.OffendingCargo) == 0 {
310			return ""
311		}
312		return x.OffendingCargo[0]
313	}
314	
315	// canonicalKey 生成调整内容的规范化键：操作种类、货物、目标舱位相同
316	// 即视为相同内容，排列顺序不影响判断。编号识别与逐条校验共用
317	// normalizeOp：只去首尾空白、按原始字节精确比较，任何字节差异都视为
318	// 不同内容，包含无效 UTF-8 字节的编号与包含 Unicode 替代字符 U+FFFD
319	// 的编号也不相同；卸下操作忽略目标舱位（执行时同样忽略），其目标值
320	// 不影响内容判断，装载与移动的目标舱位参与比较。
321	func canonicalKey(ops []Op) string {
322		sorted := make([]Op, len(ops))
323		for i, op := range ops {
324			sorted[i] = normalizeOp(op)
325		}
326		sort.Slice(sorted, func(i, j int) bool {
327			if sorted[i].Kind != sorted[j].Kind {
328				return sorted[i].Kind < sorted[j].Kind
329			}
330			if sorted[i].CargoID != sorted[j].CargoID {
331				return sorted[i].CargoID < sorted[j].CargoID
332			}
333			return sorted[i].Target < sorted[j].Target
334		})
335		// 长度前缀编码保留原始字节，不做任何字符集层面的规整，
336		// 任意字节内容都不会因分隔符或转义而碰撞。
337		var b strings.Builder
338		for _, op := range sorted {
339			b.WriteString(strconv.Itoa(int(op.Kind)))
340			b.WriteByte('|')
341			writeRawField(&b, op.CargoID)
342			writeRawField(&b, op.Target)
343		}
344		return b.String()
345	}
346	
347	// writeRawField 以“长度:原始字节”的形式写入一个字段。
348	func writeRawField(b *strings.Builder, s string) {
349		b.WriteString(strconv.Itoa(len(s)))
350		b.WriteByte(':')
351		b.WriteString(s)
352	}
353

